/// <summary>
/// find or creates record
/// </summary>
/// <param name = "_ndxUtilitasDataRecId">NDXUtilitasData RecId</param>
/// <param name = "_value">keyword value</param>
/// <returns>NDXUtilitasDataKeyWords record</returns>
static public NDXUtilitasDataKeyWords findOrCreateByObject(RefRecId _ndxUtilitasDataRecId, str _value)
{
    NDXUtilitasDataKeyWords lNDXUtilitasDataKeyWords;

    str value = strLRTrim(_value);

    if(_ndxUtilitasDataRecId)
    {
        lNDXUtilitasDataKeyWords = NDXUtilitasDataKeyWords::findRecId(_ndxUtilitasDataRecId, value, true);

        if(!lNDXUtilitasDataKeyWords && value != '')
        {
            lNDXUtilitasDataKeyWords.NDXUtilitasDataRefRecId = _ndxUtilitasDataRecId;
            lNDXUtilitasDataKeyWords.insert();
        }

        if(lNDXUtilitasDataKeyWords)
        {
            lNDXUtilitasDataKeyWords.KeyWord = value;

            ttsbegin;
            lNDXUtilitasDataKeyWords.doUpdate();
            ttscommit;
        }
    }

    return lNDXUtilitasDataKeyWords;
}

/// <summary>
/// find a record
/// </summary>
/// <param name = "_ndxUtilitasDataRecId">NDXUtilitasData RecId</param>
/// <param name = "_value">keyword value</param>
/// <param name = "_forUpdate">for update</param>
/// <returns>NDXUtilitasDataKeyWords record</returns>
static public NDXUtilitasDataKeyWords findRecId(RefRecId _ndxUtilitasDataRecId, str _value, boolean _forUpdate = false)
{
    NDXUtilitasDataKeyWords lNDXUtilitasDataKeyWords;

    lNDXUtilitasDataKeyWords.selectForUpdate(_forUpdate);

    select lNDXUtilitasDataKeyWords
        where lNDXUtilitasDataKeyWords.RecId == _ndxUtilitasDataRecId
        && lNDXUtilitasDataKeyWords.KeyWord == _value;

    return lNDXUtilitasDataKeyWords;
}
